export class BasketProductsData {
    constructor(events) {
        this.events = events;
        this._basketProducts = [];
    }
    get basketProducts() {
        return this._basketProducts;
    }
    get basketGetProd() {
        return this._basketProducts.filter((product) => product.price !== null);
    }
    basketAddProd(product) {
        this._basketProducts = [product, ...this._basketProducts];
        this.events.emit('basket:changed');
    }
    basketDelProd(productId) {
        this._basketProducts = this._basketProducts.filter((product) => product.id !== productId);
        this.events.emit('basket:changed');
    }
    isEmptyBasket() {
        return this.getSummPrice() === 0;
    }
    getNumber() {
        return this._basketProducts.length;
    }
    basketClear() {
        this._basketProducts = [];
        this.events.emit('basket:changed');
    }
    inBasket(id) {
        return this._basketProducts.some((product) => {
            return product.id === id;
        });
    }
    getSummPrice() {
        return this._basketProducts.reduce((total, product) => {
            if (product.price === null) {
                return total;
            }
            return (total += product.price);
        }, 0);
    }
}
